
import streamlit as st
import pandas as pd
import matplotlib.pyplot as plt
import os
import joblib

st.set_page_config(
    page_title="Customer Churn Predictor",
    page_icon="📊",
    layout="wide",
)

st.title("📊 Customer Churn Prediction System")
st.markdown(
    "Analyze customer information and estimate churn risk "
    "using a machine learning model."
)

MODEL_PATH = "churn_model.joblib"
DATA_PATH = "customer_data.csv"

# The model and CSV must be generated by train_model.py first.
if not os.path.exists(MODEL_PATH) or not os.path.exists(DATA_PATH):
    st.warning(
        "The trained model or sample dataset is missing. "
        "Run train_model.py locally first, then place the generated "
        "files in this repository."
    )
    st.stop()

bundle = joblib.load(MODEL_PATH)
model = bundle["model"]
features = bundle["features"]

df = pd.read_csv(DATA_PATH)

# Sidebar navigation
st.sidebar.title("Navigation")
page = st.sidebar.radio(
    "Choose a page",
    ["Dashboard", "Predict Churn", "Dataset Explorer"],
)

if page == "Dashboard":
    st.header("Business Overview")

    total_customers = len(df)
    churned = int(df["churn"].sum())
    retained = total_customers - churned
    churn_rate = churned / total_customers * 100 if total_customers else 0

    col1, col2, col3, col4 = st.columns(4)
    col1.metric("Total Customers", f"{total_customers:,}")
    col2.metric("Churned Customers", f"{churned:,}")
    col3.metric("Retained Customers", f"{retained:,}")
    col4.metric("Churn Rate", f"{churn_rate:.1f}%")

    st.subheader("Churn Distribution")

    counts = df["churn"].map(
        {0: "Retained", 1: "Churned"}
    ).value_counts()

    fig, ax = plt.subplots()
    counts.plot(kind="bar", ax=ax)
    ax.set_xlabel("Customer Status")
    ax.set_ylabel("Number of Customers")
    ax.tick_params(axis="x", rotation=0)
    st.pyplot(fig)
    plt.close(fig)

    st.caption(
        "This dashboard currently uses synthetic demonstration data."
    )

elif page == "Predict Churn":
    st.header("Predict Customer Churn")
    st.write("Enter the customer's information below.")

    with st.form("prediction_form"):
        col1, col2 = st.columns(2)

        with col1:
            tenure = st.slider(
                "Tenure (months)", 0, 72, 24
            )
            monthly_charges = st.number_input(
                "Monthly Charges", min_value=10.0,
                max_value=150.0, value=60.0
            )
            support_calls = st.slider(
                "Support Calls", 0, 12, 2
            )

        with col2:
            usage = st.number_input(
                "Usage", min_value=0.0,
                max_value=200.0, value=80.0
            )
            contract_length = st.slider(
                "Contract Length (months)", 1, 36, 12
            )
            payment_score = st.slider(
                "Payment Score", 0, 10, 7
            )

        submitted = st.form_submit_button(
            "Predict Churn Risk"
        )

    if submitted:
        customer = pd.DataFrame([{
            "tenure": tenure,
            "monthly_charges": monthly_charges,
            "support_calls": support_calls,
            "usage": usage,
            "contract_length": contract_length,
            "payment_score": payment_score,
        }])[features]

        probability = model.predict_proba(customer)[0][1]
        prediction = int(model.predict(customer)[0])

        st.subheader("Prediction Result")
        st.metric("Estimated Churn Probability", f"{probability:.1%}")
        st.progress(float(probability))

        if prediction == 1:
            st.warning(
                "The model predicts this customer may churn."
            )
        else:
            st.success(
                "The model predicts this customer may be retained."
            )

        st.caption(
            "This is a model estimate from synthetic training data, "
            "not a validated real-world risk assessment."
        )

elif page == "Dataset Explorer":
    st.header("Dataset Explorer")

    st.write("Preview of the demonstration dataset")
    st.dataframe(df.head(100), use_container_width=True)

    st.subheader("Summary Statistics")
    st.dataframe(
        df.describe().round(2),
        use_container_width=True,
    )

    st.download_button(
        "Download Dataset as CSV",
        data=df.to_csv(index=False),
        file_name="customer_data.csv",
        mime="text/csv",
    )
